group {\"className\":\"is-style-section-4\",\"style\":{\"position\":{\"type\":\"\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group is-style-section-4\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--20);padding-right:0;padding-bottom:var(--wp--preset--spacing--20);padding-left:0\"><!-- wp:paragraph -->\n<p>Get Involved</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:social-links {\"iconColor\":\"base\",\"iconColorValue\":\"#FFFFFF\",\"className\":\"is-style-logos-only\"} -->\n<ul class=\"wp-block-social-links has-icon-color is-style-logos-only\"><!-- wp:social-link {\"url\":\"https://www.facebook.com/shasa.energy/\",\"service\":\"facebook\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://www.youtube.com/@stevecolman837\",\"service\":\"youtube\"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"75%\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column\" style=\"flex-basis:75%\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:0;padding-right:var(--wp--preset--spacing--50);padding-bottom:0;padding-left:var(--wp--preset--spacing--50)\"><!-- wp:site-logo {\"width\":451,\"style\":{\"color\":{\"duotone\":\"unset\"},\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null}}} /-->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-small-font-size\">The Southcoast Health and Sustainability Alliance (SHASA) is an alliance of Eurobodalla community members. Formed in 2014 SHASA’s key focus is to highlight and support action to mitigate climate change for our region.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-small-font-size\">SHASA recognises Aboriginal people of the Yuin Nation as the original inhabitants and custodians of all land and water in the Eurobodalla and respects their enduring cultural and spiritual connection to it. SHASA acknowledges the Traditional Owners of the land in which we live and we pay our respect to Elders past, present and emerging.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"25%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|80\",\"bottom\":\"var:preset|spacing|80\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--80);flex-basis:25%\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|20\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-small-font-size\"><strong>Southcoast Health<br>and<br>Sustainability Alliance</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-small-font-size\">Phone: +61 123 456 645</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\">Email: <a href=\"mailto:contact.shasa@gmail.com\">contact.shasa@gmail.com</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\"><strong>Share Our Story</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:social-links {\"iconColor\":\"base\",\"iconColorValue\":\"#FFFFFF\",\"className\":\"is-style-logos-only\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"0\",\"left\":\"var:preset|spacing|20\"},\"margin\":{\"right\":\"0\",\"left\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<ul class=\"wp-block-social-links has-icon-color is-style-logos-only\" style=\"margin-right:0;margin-left:0\"><!-- wp:social-link {\"url\":\"https://www.facebook.com/shasa.energy/\",\"service\":\"facebook\"} /-->\n\n<!-- wp:social-link {\"service\":\"linkedin\"} /-->\n\n<!-- wp:social-link {\"service\":\"x\"} /-->\n\n<!-- wp:social-link {\"service\":\"instagram\"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->','Donation','','inherit','closed','closed','','178-revision-v1','','','2025-09-16 13:14:12','2025-09-16 03:14:12','',178,'http://172.19.125.15:8080/?p=272',0,'revision','',0),(274,1,'2025-09-16 13:14:45','2025-09-16 03:14:45','','Donation','','inherit','closed','closed','','178-revision-v1','','','2025-09-16 13:14:45','2025-09-16 03:14:45','',178,'http://172.19.125.15:8080/?p=274',0,'revision','',0),(275,1,'2025-09-16 13:15:42','2025-09-16 03:15:42','<!-- wp:post-featured-image /-->\n\n<!-- wp:paragraph -->\n<p>We had an ev meeting</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:gallery {\"linkTo\":\"none\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><!-- wp:image {\"id\":277,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://172.19.125.15:8080/wp-content/uploads/2025/09/1-4.jpeg\" alt=\"\" class=\"wp-image-277\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":278,\"sizeS