raph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:cb/slide-v2 --></div></div><div class=\"cb-pagination swiper-pagination\"></div><div class=\"cb-button-prev swiper-button-prev\"></div><div class=\"cb-button-next swiper-button-next\"></div></div>\n<!-- /wp:cb/carousel-v2 -->\n\n<!-- wp:heading {\"className\":\"is-style-default\",\"style\":{\"spacing\":{\"margin\":{\"right\":\"0\",\"left\":\"0\"}}}} -->\n<h2 class=\"wp-block-heading is-style-default\" style=\"margin-right:0;margin-left:0\">Community Events</h2>\n<!-- /wp:heading -->\n\n<!-- wp:shortcode -->\n[em_events view=\"listweek\" disable_filter=\"0\" filter_elements=\"date_range\"]\n<!-- /wp:shortcode --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"is-style-default\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|base\"}}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}},\"backgroundColor\":\"accent-1\",\"textColor\":\"base\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group is-style-default has-base-color has-accent-1-background-color has-text-color has-background has-link-color\" style=\"padding-top:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:paragraph -->\n<p>Support sustainability in our community</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"backgroundColor\":\"accent-2\",\"textColor\":\"accent-1\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|accent-1\"}}},\"border\":{\"radius\":\"100px\",\"width\":\"0px\",\"style\":\"none\"},\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\",\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}}},\"fontSize\":\"medium\"} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-accent-1-color has-accent-2-b